with t(n) as (select unnest(array['cases_public', 'chat_members', 'chat_messages', 'chats', 'follows', 'found_public', 'found_stats', 'pet_card_likers', 'pet_card_likes', 'pet_cards', 'pet_cards_public', 'pet_med_logs', 'pet_meds', 'pet_meet_board', 'pet_meet_joins', 'pet_meet_msgs', 'pet_meet_people', 'pet_meets', 'pet_meets_public', 'pet_photos', 'pet_records', 'pets', 'profiles', 'recent_sightings', 'shelter_matches', 'sightings', 'sightings_public', 'sponsors_public'])),
tt as (select n, c.relkind, c.relrowsecurity rls from t left join pg_class c on c.relname=n and c.relnamespace='public'::regnamespace)
select 'T' k, n, coalesce(relkind::text,'MISSING') kind, rls::text,
 case when relkind is null then '' else
 concat_ws(',', case when has_table_privilege('authenticated','public.'||n,'SELECT') then 'S' end, case when has_table_privilege('authenticated','public.'||n,'INSERT') then 'I' end, case when has_table_privilege('authenticated','public.'||n,'UPDATE') then 'U' end, case when has_table_privilege('authenticated','public.'||n,'DELETE') then 'D' end) end auth,
 case when relkind is null then '' else concat_ws(',', case when has_table_privilege('anon','public.'||n,'SELECT') then 'S' end, case when has_table_privilege('anon','public.'||n,'INSERT') then 'I' end) end anon
from tt
union all
select 'F', r.n, coalesce(string_agg(distinct p.oid::regprocedure::text,' | '),'MISSING'), '', bool_or(has_function_privilege('authenticated',p.oid,'EXECUTE'))::text, bool_or(has_function_privilege('anon',p.oid,'EXECUTE'))::text
from unnest(array['admin_ban', 'admin_ban_member', 'admin_bans', 'admin_delete', 'admin_get_case', 'admin_list', 'admin_members', 'admin_moa_sightings', 'admin_reports', 'admin_resolve', 'admin_set_hidden', 'admin_sighting_status', 'admin_stats', 'admin_unban', 'admin_update', 'bump_view', 'can_manage_case', 'can_manage_found', 'chat_can', 'chat_hide', 'chat_list', 'chat_mark_unread', 'chat_mute', 'chat_open', 'chat_people', 'chat_pin', 'chat_react', 'chat_read', 'chat_read_all', 'chat_report', 'chat_send', 'chat_unread', 'chat_unsend', 'claim_by_email', 'claim_case', 'claim_found', 'create_case', 'create_found', 'delete_case', 'delete_found', 'delete_my_account', 'dismiss_match', 'drop_push_token', 'friend_add', 'friend_code', 'friend_find', 'friend_list', 'friend_pending', 'friend_rel', 'friend_remove', 'friend_respond', 'is_admin', 'member_card', 'my_cases', 'my_found', 'my_pending_counts', 'owner_case', 'owner_found', 'owner_sightings', 'report_content', 'report_shelter_matches', 'rotate_calendar_token', 'save_push_token', 'set_sighting_status', 'set_social_ok', 'set_username', 'update_case', 'update_found', 'user_block', 'user_report', 'username_available', 'verify_case_email']) r(n) left join pg_proc p on p.proname=r.n and p.pronamespace='public'::regnamespace group by r.n
order by 1,2;